export function getNodeFromTree(tree, id) {
    for (const node of tree) {
        if (node.id === id) {
            return node;
        }
        if (node.children != null) {
            const result = getNodeFromTree(node.children, id);
            if (result != null) {
                return result;
            }
        }
    }
}
export function addNodeToTree(tree, parentId, node) {
    const parent = getNodeFromTree(tree, parentId);
    if (parent != null) {
        if (parent.children == null) {
            parent.children = [];
        }
        parent.children.push(node);
    }
}
//This gets the parent, which is not the grandparent or great grandparent.
export function getTreeNodeParent(tree, id, count) {
    let parent;
    //This is pretty easy. Just traverse the tree to find the node with the passed in id.
    //When we find it, stop looping and save the parent.
    traverseTree(tree, (node, parentNode) => {
        if (node.id === id) {
            parent = parentNode;
            return true;
        }
    });
    return parent;
}
export function removeNodeFromTree(tree, id) {
    //First check the root array.
    for (let i = 0; i < tree.length; i++) {
        const child = tree[i];
        if (child.id === id) {
            tree.splice(i, 1);
            return child;
        }
    }
    //If it wasn't found in the root array, check the rest of the tree.
    const parent = getTreeNodeParent(tree, id);
    if (parent != null && parent.children != null) {
        for (let i = 0; i < parent.children.length; i++) {
            const child = parent.children[i];
            if (child.id === id) {
                parent.children.splice(i, 1);
                if (parent.children.length === 0) {
                    delete parent.children;
                }
                return child;
            }
        }
    }
}
//If the callback returns true, the traversal will stop.
export function traverseTree(tree, callback) {
    traverseTreeRecursive(tree, callback, (treeNode) => {
        return treeNode.children;
    });
}
/**
 * Need to traverse a tree that doesn't have a property called `children`?
 * This is the function for you. Simply pass in a callback function that will return the array of
 * children.
 * @param tree An array of objects that may or may not have children.
 * @param callback The callback that gets run one each of the tree nodes
 * @param getChildren The way the algorithm access the children
 */
export function traverseTreeGeneric(tree, callback, getChildren) {
    traverseTreeRecursive(tree, callback, getChildren);
}
//returns true if the traversal should stop before complete.
function traverseTreeRecursive(tree, callback, getChildren, treeParent) {
    for (const node of tree) {
        let shortCircuit = callback(node, treeParent);
        if (shortCircuit === true) {
            return true;
        }
        const children = getChildren(node);
        if (children != null) {
            shortCircuit = traverseTreeRecursive(children, callback, getChildren, node);
            if (shortCircuit === true) {
                return true;
            }
        }
    }
    return false;
}
export function toTreeNodeHashMap(tree) {
    const map = {};
    traverseTree(tree, (node) => {
        map[node.id] = node;
    });
    return map;
}
/**
 * Creates a map with key: nodeId, value: the parent node for that nodeId.
 * @param tree
 * @returns
 */
export function toTreeParentNodeHashMap(tree) {
    const map = {};
    traverseTree(tree, (node, parentNode) => {
        if (parentNode != null) {
            map[node.id] = parentNode;
        }
    });
    return map;
}
/**
 * Gets a list of the ancestor node ids for the target node id.
 * @param id The id of the target node
 * @param tree The tree to search through
 * @returns An Array of the ancestor nodes for the target node id.
 */
export function getAncestorsOf(id, tree) {
    const parentMap = toTreeParentNodeHashMap(tree);
    let p = parentMap[id];
    let pid = id;
    const ancestorList = [];
    while (p != null) {
        ancestorList.push(pid);
        p = parentMap[pid];
        pid = p === null || p === void 0 ? void 0 : p.id;
    }
    return ancestorList;
}
